module compute_convex_score(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input [2:0] N,\n    input [15:0] x0, x1, x2, x3, x4, x5, x6, x7,\n    input [15:0] y0, y1, y2, y3, y4, y5, y6, y7,\n    output reg [31:0] result,\n    output reg done\n);\n\n    localparam [31:0] MOD_VAL = 32'd998244353;\n    localparam [3:0] STATE_IDLE = 4'd0;\n    localparam [3:0] STATE_CALC_BASE = 4'd1;\n    localparam [3:0] STATE_INIT_I = 4'd2;\n    localparam [3:0] STATE_INIT_J = 4'd3;\n    localparam [3:0] STATE_INIT_K = 4'd4;\n    localparam [3:0] STATE_CHECK_K = 4'd5;\n    localparam [3:0] STATE_COLLINEAR = 4'd6;\n    localparam [3:0] STATE_NEXT_K = 4'd7;\n    localparam [3:0] STATE_EVAL_COUNT = 4'd8;\n    localparam [3:0] STATE_COMPUTE_PENALTY = 4'd9;\n    localparam [3:0] STATE_SUB_PENALTY = 4'd10;\n    localparam [3:0] STATE_NEXT_J = 4'd11;\n    localparam [3:0] STATE_NEXT_I = 4'd12;\n    localparam [3:0] STATE_FINISH = 4'd13;\n\n    reg [3:0] state, next_state;\n    reg [2:0] current_i, current_j, current_k;\n    reg [3:0] point_count;\n    reg [31:0] base_score_reg;\n    reg [31:0] penalty_val;\n    reg [31:0] result_reg;\n\n    wire [15:0] xi, yi, xj, yj, xk, yk;\n    assign xi = (current_i == 3'd0) ? x0 :\n               (current_i == 3'd1) ? x1 :\n               (current_i == 3'd2) ? x2 :\n               (current_i == 3'd3) ? x3 :\n               (current_i == 3'd4) ? x4 :\n               (current_i == 3'd5) ? x5 :\n               (current_i == 3'd6) ? x6 : x7;\n    assign yi = (current_i == 3'd0) ? y0 :\n               (current_i == 3'd1) ? y1 :\n               (current_i == 3'd2) ? y2 :\n               (current_i == 3'd3) ? y3 :\n               (current_i == 3'd4) ? y4 :\n               (current_i == 3'd5) ? y5 :\n               (current_i == 3'd6) ? y6 : y7;\n    assign xj = (current_j == 3'd0) ? x0 :\n               (current_j == 3'd1) ? x1 :\n               (current_j == 3'd2) ? x2 :\n               (current_j == 3'd3) ? x3 :\n               (current_j == 3'd4) ? x4 :\n               (current_j == 3'd5) ? x5 :\n               (current_j == 3'd6) ? x6 : x7;\n    assign yj = (current_j == 3'd0) ? y0 :\n               (current_j == 3'd1) ? y1 :\n               (current_j == 3'd2) ? y2 :\n               (current_j == 3'd3) ? y3 :\n               (current_j == 3'd4) ? y4 :\n               (current_j == 3'd5) ? y5 :\n               (current_j == 3'd6) ? y6 : y7;\n    assign xk = (current_k == 3'd0) ? x0 :\n               (current_k == 3'd1) ? x1 :\n               (current_k == 3'd2) ? x2 :\n               (current_k == 3'd3) ? x3 :\n               (current_k == 3'd4) ? x4 :\n               (current_k == 3'd5) ? x5 :\n               (current_k == 3'd6) ? x6 : x7;\n    assign yk = (current_k == 3'd0) ? y0 :\n               (current_k == 3'd1) ? y1 :\n               (current_k == 3'd2) ? y2 :\n               (current_k == 3'd3) ? y3 :\n               (current_k == 3'd4) ? y4 :\n               (current_k == 3'd5) ? y5 :\n               (current_k == 3'd6) ? y6 : y7;\n\n    wire signed [15:0] dx1 = xj - xi;\n    wire signed [15:0] dy1 = yj - yi;\n    wire signed [15:0] dx2 = xk - xi;\n    wire signed [15:0] dy2 = yk - yi;\n    wire signed [31:0] prod1 = dx1 * dy2;\n    wire signed [31:0] prod2 = dx2 * dy1;\n    wire collinear = (prod1 == prod2);\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= STATE_IDLE;\n            current_i <= 3'd0;\n            current_j <= 3'd0;\n            current_k <= 3'd0;\n            point_count <= 4'd0;\n            base_score_reg <= 32'd0;\n            penalty_val <= 32'd0;\n            result_reg <= 32'd0;\n            done <= 1'b0;\n            result <= 32'd0;\n        end else begin\n            state <= next_state;\n\n            case (state)\n                STATE_IDLE: begin\n                    done <= 1'b0;\n                    current_i <= 3'd0;\n                    current_j <= 3'd0;\n                    current_k <= 3'd0;\n                    if (start) next_state <= STATE_CALC_BASE;\n                    else next_state <= STATE_IDLE;\n                end\n\n                STATE_CALC_BASE: begin\n                    if (N == 3'd0) base_score_reg <= 32'd0;\n                    else begin\n                        base_score_reg <= ((32'd1 << N) - 32'd1 - {29'd0, N} - (N * (N - 3'd1) / 2)) % MOD_VAL;\n                    end\n                    result_reg <= base_score_reg;\n                    next_state <= STATE_INIT_I;\n                end\n\n                STATE_INIT_I: begin\n                    current_i <= 3'd0;\n                    if (N < 3'd2) next_state <= STATE_FINISH;\n                    else next_state <= STATE_INIT_J;\n                end\n\n                STATE_INIT_J: begin\n                    current_j <= current_i + 3'd1;\n                    if (current_j >= N) begin\n                        next_state <= STATE_NEXT_I;\n                    end else begin\n                        point_count <= 4'd2;\n                        next_state <= STATE_INIT_K;\n                    end\n                end\n\n                STATE_INIT_K: begin\n                    current_k <= 3'd0;\n                    next_state <= STATE_CHECK_K;\n                end\n\n                STATE_CHECK_K: begin\n                    if (current_k >= N) next_state <= STATE_EVAL_COUNT;\n                    else if ((current_k == current_i) || (current_k == current_j)) next_state <= STATE_NEXT_K;\n                    else next_state <= STATE_COLLINEAR;\n                end\n\n                STATE_COLLINEAR: begin\n                    if (collinear) point_count <= point_count + 4'd1;\n                    next_state <= STATE_NEXT_K;\n                end\n\n                STATE_NEXT_K: begin\n                    current_k <= current_k + 3'd1;\n                    next_state <= STATE_CHECK_K;\n                end\n\n                STATE_EVAL_COUNT: begin\n                    if (point_count >= 4'd3) next_state <= STATE_COMPUTE_PENALTY;\n                    else next_state <= STATE_NEXT_J;\n                end\n\n                STATE_COMPUTE_PENALTY: begin\n                    penalty_val <= ((32'd1 << point_count) - 32'd1 - {28'd0, point_count} - (point_count * (point_count - 4'd1) / 2)) % MOD_VAL;\n                    next_state <= STATE_SUB_PENALTY;\n                end\n\n                STATE_SUB_PENALTY: begin\n                    if (result_reg >= penalty_val) result_reg <= result_reg - penalty_val;\n                    else result_reg <= MOD_VAL - (penalty_val - result_reg);\n                    next_state <= STATE_NEXT_J;\n                end\n\n                STATE_NEXT_J: begin\n                    current_j <= current_j + 3'd1;\n                    if (current_j >= N) next_state <= STATE_NEXT_I;\n                    else next_state <= STATE_INIT_K;\n                end\n\n                STATE_NEXT_I: begin\n                    current_i <= current_i + 3'd1;\n                    if (current_i >= (N - 3'd1)) next_state <= STATE_FINISH;\n                    else next_state <= STATE_INIT_J;\n                end\n\n                STATE_FINISH: begin\n                    done <= 1'b1;\n                    next_state <= STATE_IDLE;\n                end\n\n                default: next_state <= STATE_IDLE;\n            endcase\n            result <= result_reg;\n        end\n    end\n\nendmodule